// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web)
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

JsonTypeInfo<Person> typeInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {typeInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---

// 2a. Should succeed – the resolver can handle Person.
if (options.TryGetTypeInfo<Person>(out var personInfo))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {personInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false");

// 2b. Options with a resolver that rejects Secret – TryGet returns false.
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) =>
        {
            if (ti.Type == typeof(Secret))
                throw new NotSupportedException("Secret is not allowed");
        }}
    }
};

if (restricted.TryGetTypeInfo<Secret>(out var secretInfo))
    Console.WriteLine($"TryGetTypeInfo<Secret> succeeded: {secretInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Secret> returned false – no exception thrown!");

public record Person(string Name, int Age);
public record Secret(string Value);
